fun test_update_collateral() {
    use sui::test_scenario;
    use math::float;

    let mut scenario = test_scenario::begin(@0x1);
    let ctx = scenario.ctx();

    let mut registry = new_e_mode_registry(ctx);
    let group1 = registry.new_emode_group(0, scenario.ctx());

    // Create and support asset
    let params = new_emode_params(
        float::from_quotient(80, 100),
