    // Create and support asset with initial limiters
    let params = new_emode_params(
        float::from_quotient(80, 100),
        float::from_quotient(85, 100),
        float::from_quotient(5, 100),
        1000000000,
        float::from_quotient(110, 100),
        float::from_quotient(1, 1000),
        limiter::create_new_limiter_change(5000000000, 86400, 3600), // 5B per day
        limiter::create_new_limiter_change(2000000000, 86400, 3600), // 2B per day
    );

    registry.support_asset<TestCoinA>(group1, params, scenario.ctx());

