public(package) fun handle_repay<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    mut coin: Coin<CoinType>,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CoinType>, Decimal, Decimal) {
    assert!(coin.value() != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();

    let asset = self.assets.load_mut_by_type(name);
    let min_borrow_amount = asset.asset_config().min_borrow_amount();

    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());


    let obligation_old_borrow_amount = obligation.debt(name).unsafe_debt_amount();


    let borrow_index = reserve.borrow_index().value();
    let residule = obligation.repay_debt<MarketType, CoinType>(coin.value(), borrow_index);
    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);

    // interest updated, should be up to date
    let obligation_new_borrow_amount = if (obligation.has_debt(name)) obligation.debt(name).unsafe_debt_amount() else float::zero();

    let refund = coin.split(residule, ctx);

    let emode_group_id = obligation.emode_group();

    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_borrow_amount, obligation_new_borrow_amount);

    let emode = emode_group.borrow_emode_mut(name);
    emode.borrow_mut_borrow_limiter().reduce_outflow(now, coin.value());


    reserve.repay_amount(coin);

    // try stop adl, if there is one on going
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
    // use ceiling, slighly more 
    adl.try_stop_borrow_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), emode_group_id, emode_group_total_borrow.ceil());

    (refund, borrow_index, obligation_new_borrow_amount)
}

